  'filipino-article-proof-boundaries': { lens:'proof boundaries for Filipino article production', artifact:'a claim ledger classifying facts, guidance, examples, and statements needing owner evidence', risk:'a polished sentence can quietly overstate what the available source proves', example:'a remote worker describing a control without claiming that the control produced a measured outcome', owner:'the accountable owner for sensitive or company-specific assertions', check:'major edits are followed by a fresh claim review', input:'sentence purpose, source, confidence, reader action, and escalation status', boundary:'filling an evidence gap with invented history, credentials, testimonials, or outcomes is prohibited', handoff:'the editor receives both the proposed copy and the reason a claim is bounded', review:'which unsupported-claim corrections repeat because the brief is underspecified' },
